import {readFile,writeFile} from 'node:fs/promises';
const path='scripts/relatorio-revisao-integral-20261119.mjs';let s=await readFile(path,'utf8');
const marcador='<h2 id="testes">Testes e alcance real da validação</h2>';
const trecho='<h2>O que ainda aparece nos picos</h2><p>As medianas melhoraram nos oito módulos medidos, em ambos os dispositivos; o P95 também caiu. Isso não significa que cada abertura ficou mais rápida. O maior tempo do Histórico no celular aumentou de 1,946 para 2,442 s. Nesse caso de borracharia, a requisição de acesso subiu de 0,458 para 1,417 s, enquanto o intervalo de frontend entre o fim do acesso e a consulta caiu de 0,550 para 0,091 s. A rodada mostra onde ocorreu a espera; não permite atribuir tudo à internet ou tudo ao SQL.</p><p>Em Relatórios de manutenção de equipamentos no celular, a consulta passou de 0,802 para 1,403 s; a espera do frontend caiu de 0,513 para 0,100 s. A consulta acumulada de relatórios de serviços no PostgreSQL tem média histórica de 234,553 ms, mas esse acumulado mistura versões e usuários: não identifica a execução desse pico. Os picos de API permanecem documentados, sem declaração de resolução completa da infraestrutura.</p><p>Houve um HTTP 404 de <code>consultar_lembretes_financeiros</code>. O resultado “sem falhas de cenário” se refere à abertura dos módulos; não apaga essa falha de integração. A migração faltante precisa ser aplicada após renovar a sessão do Supabase.</p><p>As recomendações de índices foram preservadas para avaliação por plano/carga; não foram criados 189 índices indiscriminadamente nem removidos índices de filas apenas por falta de uso registrado. Referências: <a href="https://supabase.com/docs/guides/database/database-linter?lint=0001_unindexed_foreign_keys">FKs sem índice</a>, <a href="https://supabase.com/docs/guides/database/database-linter?lint=0005_unused_index">índices sem uso</a> e <a href="https://supabase.com/docs/guides/deployment/going-into-prod">configuração de produção</a>.</p>';
if(!s.includes('<h2>O que ainda aparece nos picos</h2>'))s=s.replace(marcador,trecho+marcador);
s=s.replace('Não houve publicação deste frontend.', 'Não houve publicação deste frontend nem da alteração de fotos-proposta.');
s=s.replace('Esta conferência cobre integralmente as fontes da aplicação em <code>src</code>.', 'Esta conferência cobre integralmente as fontes da aplicação em <code>src</code>; o anexo acrescenta a revisão das funções de servidor, configuração e assets públicos.');
await writeFile(path,s);
